import {useCallback, useMemo, useRef, useState} from 'react'
import {ActionList, AnchoredOverlay, Button, Flash, Stack, Link, Banner, Tooltip} from '@primer/react'
import type {ActionBarProps} from '@github-ui/action-bar'
import {AlertsListItems} from './AlertsListItems'
import {AlertsList} from './AlertsList'
import {AlertListItem} from './AlertListItem'
import {
  CodeScanningCreateBranchDialog,
  type BranchNextStep,
} from '@github-ui/code-scanning-shared/components/CodeScanningCreateBranchDialog'
import type {BranchType} from '@github-ui/code-scanning-shared/components/CreateBranchDialog'
import {SharedDismissalDialog} from '@github-ui/shared-dismissal/components/SharedDismissalDialog'
import {ALERT_ENTITY} from '@github-ui/shared-dismissal/pluralized-texts'
import {SecretScanningDismissalDialog} from './SecretScanningDismissalDialog'
import {useRepoAlertsQuery} from '../hooks/use-repo-alerts-query'
import pluralize from 'pluralize'
import {ChevronDownIcon, AgentIcon} from '@primer/octicons-react'
import {useQueryClient} from '@github-ui/react-query'
import {useAlertsParams} from '../hooks/use-alerts-params'
import {
  securityCampaignRepoCreateBranchPath,
  securityCampaignRepoAssignToCopilotPath,
  codeScanningDismissAlertsPath,
} from '@github-ui/paths'
import {useAssignToCopilot} from '../hooks/use-assign-to-copilot'
import {useAgenticAutofixJobPoll} from '@github-ui/code-scanning-shared/hooks/use-agentic-autofix-job-poll'
import {useBannerContext} from '@github-ui/role-assignments/banner-provider'
import type {Repository} from '../types/repository'
import {Dialog} from '@primer/react/experimental'
import type {Cursor} from '@github-ui/code-scanning-shared/types/cursor'
import {AgenticAutofixError} from '@github-ui/code-scanning-shared/types/agentic-autofix-error'
import {AgenticAutofixErrorBanner} from '@github-ui/code-scanning-shared/components/AgenticAutofixErrorBanner'

export type RepoAlertsListProps = {
  alertsPath: string
  repository: Repository
  branchListCacheKey: string
  securityCampaignNumber: number
  canCreateBranch: boolean
  canCloseAlerts: boolean
  delegatedAlertDismissalEnabled: boolean
  showAssignToCopilotButton: boolean
  canAssignAlertsToCopilot: boolean
  copilotCodingAgentDocsUrl: string
  alertType?: 'code_scanning' | 'secret_scanning'
  allowAllAlertsForCopilotAssignment: boolean
  useAgenticAutofix: boolean
}

export function RepoAlertsList({
  alertsPath,
  repository,
  branchListCacheKey,
  securityCampaignNumber,
  canCreateBranch,
  canCloseAlerts,
  delegatedAlertDismissalEnabled,
  showAssignToCopilotButton,
  canAssignAlertsToCopilot,
  copilotCodingAgentDocsUrl,
  alertType = 'code_scanning',
  allowAllAlertsForCopilotAssignment,
  useAgenticAutofix,
}: RepoAlertsListProps) {
  const [selectedItems, setSelectedItems] = useState<Set<number>>(() => new Set<number>())
  const onSelect = useCallback(
    (id: number, selected: boolean) => {
      setSelectedItems(prev => {
        const newSelectedItems = new Set<number>(prev)
        if (selected) {
          newSelectedItems.add(id)
        } else {
          newSelectedItems.delete(id)
        }
        return newSelectedItems
      })
    },
    [setSelectedItems],
  )

  const chooseBranchTypeAnchorRef = useRef(null)
  const [showChooseBranchType, setShowChooseBranchType] = useState(false)
  const [selectedBranchType, setSelectedBranchType] = useState<BranchType>('new')

  const [showCreateBranchDialog, setShowCreateBranchDialog] = useState(false)

  const handleChooseBranchType = (branchType: BranchType) => {
    setSelectedBranchType(branchType)
    setShowCreateBranchDialog(true)
  }

  const queryClient = useQueryClient()

  const handleBranchSuccess = (nextStep: BranchNextStep) => {
    if (nextStep !== 'none') {
      queryClient.invalidateQueries({queryKey: ['repo-alerts', alertsPath]})
    }
  }
  const handleBranchClose = () => {
    setShowCreateBranchDialog(false)
    setSelectedItems(new Set())
  }

  const [showSharedDismissalDialog, setShowSharedDismissalDialog] = useState(false)

  const handleCloseAs = () => {
    setShowSharedDismissalDialog(true)
  }

  const {query, cursor, onQueryChange, onCursorChange} = useAlertsParams()

  const onStateFilterChange = useCallback(
    (state: 'open' | 'closed' | 'all') => onQueryChange(`is:${state}`),
    [onQueryChange],
  )

  const alertsQuery = useRepoAlertsQuery(alertsPath, {query, cursor})

  const alerts = useMemo(() => alertsQuery.data?.alerts ?? [], [alertsQuery.data])

  const onToggleSelectAll = useCallback(
    (isSelectAllChecked: boolean) => {
      setSelectedItems(new Set<number>(isSelectAllChecked ? alerts.map(alert => alert.number) : []))
    },
    [setSelectedItems, alerts],
  )

  const selectedCount = selectedItems.size
  const closedSelectedAlertsCount = alerts.filter(
    alert => selectedItems.has(alert.number) && (alert.isDismissed || alert.isFixed),
  ).length
  const allSelectedAlertsAreClosed = selectedCount === closedSelectedAlertsCount
  const someSelectedAlertsAreClosed = closedSelectedAlertsCount > 0

  const selectedAlertsWithSuggestedFixes = alerts.filter(
    alert => selectedItems.has(alert.number) && alert.hasSuggestedFix,
  )
  const selectedItemsWithSuggestedFixes = selectedAlertsWithSuggestedFixes.map(alert => alert.number)
  const firstAlertWithSuggestedFixTitle = selectedAlertsWithSuggestedFixes[0]?.title ?? ''

  const handleCreateBranch = useCallback(() => {
    if (!useAgenticAutofix && selectedItemsWithSuggestedFixes.length > 0) {
      setShowChooseBranchType(true)
    } else {
      setSelectedBranchType('new')
      setShowChooseBranchType(false)
      setShowCreateBranchDialog(true)
    }
  }, [selectedItemsWithSuggestedFixes.length, useAgenticAutofix])

  const {
    mutate: mutateAssignToCopilot,
    isPending: isAssignToCopilotPending,
    error: assignToCopilotError,
    reset: resetAssignToCopilot,
  } = useAssignToCopilot(
    securityCampaignRepoAssignToCopilotPath({
      owner: repository.ownerLogin,
      repo: repository.name,
      securityCampaignNumber,
    }),
  )

  const {showBanner} = useBannerContext()
  const [showPadawanDisabledModal, setShowPadawanDisabledModal] = useState(false)
  const [agenticAutofixJobId, setAgenticAutofixJobId] = useState<string | null>(null)

  const handleAgenticAutofixError = useCallback(
    (message: string) => {
      showBanner({
        message: `Copilot failed to create a pull request. ${message}.`,
        variant: 'critical',
      })
      setAgenticAutofixJobId(null)
    },
    [showBanner],
  )

  useAgenticAutofixJobPoll(
    repository.ownerLogin,
    repository.name,
    useAgenticAutofix ? agenticAutofixJobId : null,
    handleAgenticAutofixError,
  )

  const alertNumbersAssignedToCopilot = useMemo(() => {
    if (!useAgenticAutofix) return new Set<number>()
    return new Set(alerts.filter(a => a.assignees?.some(assignee => assignee.isCopilot)).map(a => a.number))
  }, [useAgenticAutofix, alerts])

  const allSelectedAssignedToCopilot = useMemo(() => {
    if (selectedItems.size === 0) return false
    return Array.from(selectedItems).every(num => alertNumbersAssignedToCopilot.has(num))
  }, [selectedItems, alertNumbersAssignedToCopilot])

  const handleAssignToCopilot = useCallback(async () => {
    // When CCA is enabled, allow any selection. Otherwise, require suggested fixes.
    let alertNumbersToAssign = allowAllAlertsForCopilotAssignment
      ? Array.from(selectedItems)
      : selectedItemsWithSuggestedFixes

    // When using agentic autofix, skip alerts already assigned to Copilot
    if (useAgenticAutofix) {
      alertNumbersToAssign = alertNumbersToAssign.filter(num => !alertNumbersAssignedToCopilot.has(num))
    }

    if (alertNumbersToAssign.length <= 0) {
      return
    }

    // If user doesn't have padawan copilot agent enabled, show the modal to commit fixes manually
    if (!canAssignAlertsToCopilot) {
      setShowPadawanDisabledModal(true)
      return
    }

    mutateAssignToCopilot(
      {
        alertNumbers: alertNumbersToAssign,
      },
      {
        onSuccess: data => {
          showBanner({
            message: useAgenticAutofix
              ? 'Successfully assigned to Copilot to generate fixes for the selected alerts. Copilot will open a pull request.'
              : 'Successfully assigned to Copilot to apply the autofixes for selected alerts. Copilot will open a PR.',
            variant: 'success',
          })

          if (data.agenticAutofixJobId) {
            setAgenticAutofixJobId(data.agenticAutofixJobId)
          }

          void queryClient.invalidateQueries({queryKey: ['repo-alerts', alertsPath]})
        },
      },
    )
  }, [
    canAssignAlertsToCopilot,
    selectedItemsWithSuggestedFixes,
    selectedItems,
    alertNumbersAssignedToCopilot,
    allowAllAlertsForCopilotAssignment,
    mutateAssignToCopilot,
    showBanner,
    queryClient,
    alertsPath,
    useAgenticAutofix,
  ])

  const actions = useMemo<ActionBarProps['actions']>(() => {
    const visibleActions: ActionBarProps['actions'] = []

    const isSecretScanning = alertType === 'secret_scanning'

    // Assign to Copilot button (code scanning only)
    const isAlertWithNoFixSelected = selectedItemsWithSuggestedFixes.length !== selectedCount

    // Determine when the "Assign to Copilot" button should be inactive and why
    let isAssignToCopilotInactive = false
    let inactiveText: string | undefined

    if (isAssignToCopilotPending) {
      // Always inactive while an assignment request is pending
      isAssignToCopilotInactive = true
    } else if (useAgenticAutofix && allSelectedAssignedToCopilot) {
      // When using agentic autofix: inactive if all selected alerts already assigned to Copilot
      isAssignToCopilotInactive = true
      inactiveText = 'Copilot is already assigned'
    } else if (!allowAllAlertsForCopilotAssignment && isAlertWithNoFixSelected) {
      // When "all rules" mode is disabled: inactive if any alert lacks a suggested fix
      isAssignToCopilotInactive = true
      inactiveText = `Ensure selected alerts have autofix suggestions.`
    }

    const assignToCopilotButton = (
      <Button
        loading={isAssignToCopilotPending}
        inactive={isAssignToCopilotInactive}
        onClick={!isAssignToCopilotInactive ? handleAssignToCopilot : undefined}
        leadingVisual={AgentIcon}
      >
        Assign to Copilot
      </Button>
    )
    if (!isSecretScanning && selectedCount > 0 && showAssignToCopilotButton) {
      visibleActions.push({
        key: 'assignToCopilot',
        render: (isOverflowMenu: boolean) => {
          const overflowMenu = (
            <ActionList.Item
              loading={isAssignToCopilotPending}
              inactiveText={inactiveText}
              onSelect={!isAssignToCopilotInactive ? handleAssignToCopilot : undefined}
            >
              <ActionList.LeadingVisual>
                <AgentIcon />
              </ActionList.LeadingVisual>
              Assign to Copilot
            </ActionList.Item>
          )
          const noOverflowMenu =
            isAssignToCopilotInactive && inactiveText ? (
              <Tooltip text={inactiveText}>{assignToCopilotButton}</Tooltip>
            ) : (
              assignToCopilotButton
            )
          return isOverflowMenu ? overflowMenu : noOverflowMenu
        },
      })
    }

    // Commit autofixes / create branch (code scanning only)
    if (!isSecretScanning && selectedCount > 0 && canCreateBranch) {
      visibleActions.push({
        key: 'createBranch',
        render: isOverflowMenu => {
          const showCommitAutofixButton = !useAgenticAutofix && selectedItemsWithSuggestedFixes.length > 0
          const textAndIcon = showCommitAutofixButton ? (
            <Stack direction="horizontal" align="center" gap="condensed">
              {`Commit ${pluralize('autofix', selectedItemsWithSuggestedFixes.length)}`}
              <ChevronDownIcon />
            </Stack>
          ) : (
            'Create new branch'
          )
          if (isOverflowMenu) {
            return showCommitAutofixButton ? (
              <ActionList>
                <ActionList.Item onSelect={() => handleChooseBranchType('new')}>
                  Commit {pluralize('autofix', selectedItemsWithSuggestedFixes.length)} to new branch
                </ActionList.Item>
                <ActionList.Item onSelect={() => handleChooseBranchType('existing')}>
                  Commit {pluralize('autofix', selectedItemsWithSuggestedFixes.length)} to existing branch
                </ActionList.Item>
              </ActionList>
            ) : (
              <ActionList.Item
                ref={chooseBranchTypeAnchorRef}
                aria-haspopup={showCommitAutofixButton}
                aria-expanded={showChooseBranchType}
                disabled={allSelectedAlertsAreClosed}
                onSelect={handleCreateBranch}
              >
                {textAndIcon}
              </ActionList.Item>
            )
          }

          return (
            <Button
              ref={chooseBranchTypeAnchorRef}
              aria-haspopup={showCommitAutofixButton}
              aria-expanded={showChooseBranchType}
              disabled={allSelectedAlertsAreClosed}
              onClick={handleCreateBranch}
            >
              {textAndIcon}
            </Button>
          )
        },
      })
    }

    // Close Alerts button (always available)
    if (selectedCount > 0 && canCloseAlerts) {
      visibleActions.push({
        key: 'closeAlerts',
        render: (isOverflowMenu: boolean) => {
          const buttonText =
            alertType === 'secret_scanning' && allSelectedAlertsAreClosed
              ? `Reopen ${pluralize('alert', selectedCount)}`
              : `Dismiss ${pluralize('alert', selectedCount)}`
          const isDisabled = alertType === 'secret_scanning' ? false : allSelectedAlertsAreClosed

          return isOverflowMenu ? (
            <ActionList.Item
              aria-haspopup="true"
              aria-expanded={showSharedDismissalDialog}
              disabled={isDisabled}
              onSelect={handleCloseAs}
            >
              {buttonText}
            </ActionList.Item>
          ) : (
            <Button
              aria-haspopup="true"
              aria-expanded={showSharedDismissalDialog}
              disabled={isDisabled}
              onClick={handleCloseAs}
            >
              {buttonText}
            </Button>
          )
        },
      })
    }

    return visibleActions
  }, [
    canCloseAlerts,
    canCreateBranch,
    selectedItemsWithSuggestedFixes.length,
    allSelectedAlertsAreClosed,
    handleCreateBranch,
    selectedCount,
    showChooseBranchType,
    showSharedDismissalDialog,
    handleAssignToCopilot,
    isAssignToCopilotPending,
    showAssignToCopilotButton,
    alertType,
    allowAllAlertsForCopilotAssignment,
    allSelectedAssignedToCopilot,
    useAgenticAutofix,
  ])

  const handleModalOpenPullRequest = useCallback(() => {
    setShowPadawanDisabledModal(false)
    setSelectedBranchType('new')
    setShowCreateBranchDialog(true)
  }, [setShowPadawanDisabledModal, setSelectedBranchType, setShowCreateBranchDialog])

  // Clear selections when navigating between pages (cursor changes)
  const handleCursorChange = useCallback(
    (newCursor: Cursor | null) => {
      setSelectedItems(new Set())
      onCursorChange(newCursor)
    },
    [setSelectedItems, onCursorChange],
  )

  return (
    <>
      {assignToCopilotError && !(assignToCopilotError instanceof AgenticAutofixError) && (
        <Flash variant="danger">Something went wrong, please try again.</Flash>
      )}
      {assignToCopilotError && assignToCopilotError instanceof AgenticAutofixError && (
        <AgenticAutofixErrorBanner
          error={assignToCopilotError}
          repository={{
            owner: repository.ownerLogin,
            name: repository.name,
          }}
          onRetry={handleAssignToCopilot}
          onDismiss={resetAssignToCopilot}
        />
      )}
      <AlertsList
        onToggleSelectAll={onToggleSelectAll}
        openCount={alertsQuery.data?.openCount}
        closedCount={alertsQuery.data?.closedCount}
        prevCursor={alertsQuery.data?.prevCursor}
        nextCursor={alertsQuery.data?.nextCursor}
        isLoading={alertsQuery.isLoading}
        isError={alertsQuery.isError}
        query={query}
        onStateFilterChange={onStateFilterChange}
        showStateFilters={selectedCount === 0}
        onPageChange={handleCursorChange}
        setSelectedItems={setSelectedItems}
        isSelectable
        showLimitedAlertsWarning={false}
        alertType={alertType}
        actions={actions}
      >
        <AlertsListItems
          alerts={alerts}
          query={query}
          isLoading={alertsQuery.isLoading}
          isError={alertsQuery.isError}
          renderAlert={alert => (
            <AlertListItem
              alert={alert}
              onSelect={isSelected => onSelect(alert.number, isSelected)}
              isSelected={selectedItems.has(alert.number)}
              useAgenticAutofix={useAgenticAutofix}
            />
          )}
        />
      </AlertsList>
      {canCloseAlerts && showSharedDismissalDialog && (
        <>
          {alertType === 'secret_scanning' ? (
            <SecretScanningDismissalDialog
              setOpen={setShowSharedDismissalDialog}
              alertNumbers={Array.from(selectedItems)}
              alerts={alerts}
              alertStatus={allSelectedAlertsAreClosed ? 'closed' : 'open'}
              repositoryName={repository.name}
              repositoryOwner={repository.ownerLogin}
            />
          ) : (
            <SharedDismissalDialog
              setOpen={setShowSharedDismissalDialog}
              alertNumbers={Array.from(selectedItems)}
              path={codeScanningDismissAlertsPath({
                owner: repository.ownerLogin,
                repo: repository.name,
                isDelegatedAlertEnabled: delegatedAlertDismissalEnabled,
              })}
              delegatedAlertDismissalEnabled={delegatedAlertDismissalEnabled}
              entity={ALERT_ENTITY}
              campaignNumber={securityCampaignNumber}
            />
          )}
        </>
      )}
      <AnchoredOverlay
        anchorRef={chooseBranchTypeAnchorRef}
        renderAnchor={null}
        open={showChooseBranchType}
        onOpen={() => setShowChooseBranchType(true)}
        onClose={() => setShowChooseBranchType(false)}
        focusZoneSettings={{disabled: true}}
        align="end"
      >
        <ActionList>
          <ActionList.Item onSelect={() => handleChooseBranchType('new')}>Commit to new branch</ActionList.Item>
          <ActionList.Item onSelect={() => handleChooseBranchType('existing')}>
            Commit to existing branch
          </ActionList.Item>
        </ActionList>
      </AnchoredOverlay>
      {canCreateBranch && showCreateBranchDialog && (
        <CodeScanningCreateBranchDialog
          firstAlertWithSuggestedFixTitle={useAgenticAutofix ? '' : firstAlertWithSuggestedFixTitle}
          alertNumbers={Array.from(selectedItems)}
          alertNumbersWithSuggestedFixes={useAgenticAutofix ? [] : selectedItemsWithSuggestedFixes}
          repository={repository}
          branchListCacheKey={branchListCacheKey}
          createPath={securityCampaignRepoCreateBranchPath({
            owner: repository.ownerLogin,
            repo: repository.name,
            securityCampaignNumber,
          })}
          onSuccess={handleBranchSuccess}
          onClose={handleBranchClose}
          someSelectedAlertsAreClosed={someSelectedAlertsAreClosed}
          branchType={selectedBranchType}
          isCampaign
        />
      )}
      {showPadawanDisabledModal && (
        <Dialog
          title="Assign autofixes to Copilot"
          onClose={() => setShowPadawanDisabledModal(false)}
          footerButtons={[
            {
              buttonType: 'default',
              content: 'Cancel',
              onClick: () => {
                setShowPadawanDisabledModal(false)
              },
            },
            {
              buttonType: 'primary',
              content: 'Open a pull request',
              onClick: handleModalOpenPullRequest,
            },
          ]}
        >
          <div>
            <Banner
              hideTitle
              aria-label="Assign autofixes to Copilot"
              description={
                <div data-a11y-link-underlines="true">
                  To assign autofixes to Copilot, you need access to{' '}
                  <Link inline href={copilotCodingAgentDocsUrl} target="_blank" rel="noopener noreferrer">
                    {'GitHub Copilot cloud agent'}
                  </Link>
                  .
                </div>
              }
              title="Info"
              variant="upsell"
            />

            <div className="tmp-mt-3">
              <p className="tmp-mb-3">
                <span>{'Copilot cloud agent'}</span> can open a pull request and grab context around your codebase to
                implement autofixes and resolve any conflicts that may come up.
              </p>

              <p>
                You can also choose to open a pull request and assign it to Copilot later, or commit the changes
                manually.
              </p>
            </div>
          </div>
        </Dialog>
      )}
    </>
  )
}
