import {ActionList} from '@primer/react'
import {TrackingLinkOverlayActionItem} from './TrackingLinkOverlayActionItem'
import {type TrackingLink, TrackingSystem} from '@github-ui/code-scanning-shared/types/tracking-link'

export type AlertTrackingLinksOverlayContentProps = {
  trackingLinks: TrackingLink[]
}

function getItemKey(trackingLink: TrackingLink): string {
  if (trackingLink.trackingSystem === TrackingSystem.GITHUB_ISSUE && trackingLink.issue) {
    return `github-issue-${trackingLink.issue.repository.ownerLogin}-${trackingLink.issue.number}`
  }
  return `${trackingLink.trackingSystem}-${trackingLink.trackingUrl}`
}

export function AlertTrackingLinksOverlayContent({trackingLinks}: AlertTrackingLinksOverlayContentProps) {
  return (
    <ActionList>
      {trackingLinks.map(trackingLink => (
        <TrackingLinkOverlayActionItem key={getItemKey(trackingLink)} trackingLink={trackingLink} />
      ))}
    </ActionList>
  )
}
