import {ActionList} from '@primer/react'
import {IssueOpenedIcon, SkipIcon, CheckCircleIcon} from '@primer/octicons-react'
import {issuePath} from '@github-ui/paths'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {type TrackingLink, TrackingSystem} from '@github-ui/code-scanning-shared/types/tracking-link'

export type TrackingLinkOverlayActionItemProps = {
  trackingLink: TrackingLink
}

export function TrackingLinkOverlayActionItem({trackingLink}: TrackingLinkOverlayActionItemProps) {
  const getHovercardAttributesForType = useGetHovercardAttributesForType()

  // Support only rendering GitHub issue tracking links in the overlay for now
  if (trackingLink.trackingSystem !== TrackingSystem.GITHUB_ISSUE || !trackingLink.issue) {
    return null
  }

  const issue = trackingLink.issue
  const href = issuePath({
    owner: issue.repository.ownerLogin,
    repo: issue.repository.name,
    issueNumber: issue.number,
  })

  const getIssueIcon = () => {
    if (issue.state === 'open') {
      return <IssueOpenedIcon className="fgColor-open" />
    }
    if (issue.stateReason === 'not_planned' || issue.stateReason === 'duplicate') {
      return <SkipIcon className="fgColor-muted" />
    }
    return <CheckCircleIcon className="fgColor-done" />
  }

  return (
    <ActionList.LinkItem
      href={href}
      {...getHovercardAttributesForType('issue', {
        owner: issue.repository.ownerLogin,
        repo: issue.repository.name,
        issueNumber: issue.number,
      })}
    >
      <ActionList.LeadingVisual>{getIssueIcon()}</ActionList.LeadingVisual>
      {issue.title}
      <ActionList.Description variant="block">
        {issue.repository.ownerLogin}/{issue.repository.name}#{issue.number}
      </ActionList.Description>
    </ActionList.LinkItem>
  )
}
