import {Link} from '@primer/react'
import type {AlertType} from '../types/security-campaign-alert'

export interface CampaignFeedbackLinkProps {
  alertType: AlertType | undefined
}

export function CampaignFeedbackLink({alertType}: CampaignFeedbackLinkProps) {
  const feedbackUrl =
    alertType === 'secret_scanning'
      ? 'https://github.com/orgs/community/discussions/173665'
      : 'https://gh.io/security-campaigns-feedback'
  return (
    <Link className="f6 text-right" href={feedbackUrl}>
      Give feedback
    </Link>
  )
}
