import {Popover, Button, Heading} from '@primer/react'
import {useCallback, useEffect, useRef} from 'react'
import {useAnalytics, useClickAnalytics} from '@github-ui/use-analytics'
import styles from './ArtifactFiltersPopover.module.css'

const ANALYTICS_CATEGORY = 'Nudge'
const ANALYTICS_LABEL = 'surface:security-campaigns;nudge:artifact-filters'

interface ArtifactFiltersPopoverProps {
  showPopover: boolean
  onDismiss: () => void
}

export function ArtifactFiltersPopover({showPopover, onDismiss}: ArtifactFiltersPopoverProps) {
  const {sendAnalyticsEvent} = useAnalytics()
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const impressionSentRef = useRef(false)

  useEffect(() => {
    if (showPopover && !impressionSentRef.current) {
      impressionSentRef.current = true
      sendAnalyticsEvent('analytics.view', undefined, {
        category: ANALYTICS_CATEGORY,
        action: 'visible',
        label: ANALYTICS_LABEL,
      })
    }
  }, [showPopover, sendAnalyticsEvent])

  const handleDismiss = useCallback(() => {
    sendClickAnalyticsEvent({
      category: ANALYTICS_CATEGORY,
      action: 'Dismiss',
      label: ANALYTICS_LABEL,
    })
    onDismiss()
  }, [onDismiss, sendClickAnalyticsEvent])

  if (!showPopover) {
    return null
  }

  return (
    <Popover open caret="top" className={styles.Popover} data-testid="artifact-filters-popover">
      <Popover.Content className={styles.PopoverContent}>
        <Heading as="h3" className="f5 tmp-mb-3">
          Filter by artifact metadata
        </Heading>
        <p className="color-fg-muted tmp-mb-3">
          You can now prioritize alerts based on having detected deployments or runtime risks.
        </p>
        <Button size="medium" alignContent="center" onClick={handleDismiss}>
          OK, got it
        </Button>
      </Popover.Content>
    </Popover>
  )
}
