import {useState, useRef} from 'react'
import {number as formatNumber} from '@github-ui/formatters'
import {Button, CounterLabel, Flash, FormControl, Radio, RadioGroup, Stack, Textarea} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {SyncIcon} from '@primer/octicons-react'
import type {SecurityCampaignAlert} from '../types/security-campaign-alert'
import {reactFetchJSON} from '@github-ui/verified-fetch'

import {secretScanningTokenResolvePath} from '@github-ui/paths'

export interface SecretScanningDismissalDialogProps {
  setOpen: (open: boolean) => void
  alertNumbers: number[]
  alerts: SecurityCampaignAlert[]
  alertStatus?: 'open' | 'closed' // Add status to determine dismiss vs reopen
  repositoryName: string
  repositoryOwner: string
}

export const ResolutionType = {
  Revoked: 'revoked',
  Reopened: 'reopened',
  FalsePositive: 'false_positive',
  UsedInTests: 'used_in_tests',
  WontFix: 'wont_fix',
  PatternEdited: 'pattern_edited',
  PatternDeleted: 'pattern_deleted',
  HiddenByConfig: 'hidden_by_config',
} as const

export type ResolutionType = (typeof ResolutionType)[keyof typeof ResolutionType]

export function SecretScanningDismissalDialog({
  setOpen,
  alertNumbers,
  alerts,
  alertStatus = 'open',
  repositoryName,
  repositoryOwner,
}: SecretScanningDismissalDialogProps) {
  const [selectedCloseReason, setSelectedCloseReason] = useState('')
  const [isPending, setIsPending] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const dismissalComment = useRef<HTMLTextAreaElement>(null)

  const resolveURL = secretScanningTokenResolvePath(repositoryOwner, repositoryName)

  const count = alertNumbers.length
  const isReopening = alertStatus === 'closed'
  // For reopening, we don't need a reason selection, just the comment
  const isValid = isReopening || !!selectedCloseReason

  const handleRadioGroupChange = (value: string | null) => {
    setSelectedCloseReason(value ?? '')
  }

  async function handleSubmit() {
    if (!isValid) {
      return
    }

    setIsPending(true)
    setError(null)

    const alertNumberToSlug = new Map<number, string>()
    for (const alert of alerts ?? []) {
      if ('slug' in alert && alert.slug) {
        alertNumberToSlug.set(alert.number, alert.slug)
      }
    }

    const result = await reactFetchJSON(resolveURL, {
      method: 'put',
      body: {
        resolution: isReopening ? ResolutionType.Reopened : selectedCloseReason,
        dismissal_comment: dismissalComment?.current?.value ?? '',
        repository: repositoryName,
        user_id: repositoryOwner,
        id: alertNumbers,
        id_with_slug: alertNumbers.map(id => `${id}:${alertNumberToSlug.get(id)}`),
      },
    })

    setIsPending(false)

    if (!result.ok) {
      const errorText = await result.text()
      setError(errorText)
      return
    }

    setOpen(false)
    // Need to do a full page reload so that the sidebar numbers (which are not in react) get updated
    window.location.reload()
  }

  const title = isReopening
    ? count > 1
      ? `Reopen alerts`
      : 'Reopen alert'
    : count > 1
      ? `Dismiss alerts`
      : 'Dismiss alert'
  const subtitle = isReopening
    ? count > 1
      ? 'Add a comment for reopening these alerts'
      : 'Add a comment for reopening this alert'
    : count > 1
      ? 'Select a dismissal reason for these alerts'
      : 'Select a dismissal reason for this alert'
  const submitButtonLabel = isReopening
    ? count > 1
      ? 'Reopen alerts'
      : 'Reopen alert'
    : count > 1
      ? 'Dismiss alerts'
      : 'Dismiss alert'

  const reasons = {
    revokedDescription: count > 1 ? 'These secrets have been revoked' : 'This secret has been revoked',
    falsePositiveDescription: count > 1 ? 'These alerts are not valid' : 'This alert is not valid',
    usedInTestsDescription:
      count > 1 ? 'These secrets are not in production code' : 'This secret is not in production code',
    wontFixDescription: count > 1 ? 'These alerts are not relevant' : 'This alert is not relevant',
  }

  return (
    <Dialog
      width="large"
      height="auto"
      onClose={() => setOpen(false)}
      title={title}
      subtitle={subtitle}
      renderFooter={() => (
        <Dialog.Footer>
          <Button onClick={() => setOpen(false)}>Cancel</Button>
          <Button
            variant="primary"
            onClick={handleSubmit}
            disabled={!isValid || isPending}
            leadingVisual={isPending ? SyncIcon : null}
          >
            <span>{submitButtonLabel}</span>
            {count > 1 && (
              <CounterLabel scheme="primary" className="ml-2">
                {formatNumber(count)}
              </CounterLabel>
            )}
          </Button>
        </Dialog.Footer>
      )}
    >
      <Stack gap="normal">
        {error && <Flash variant="danger">{error}</Flash>}
        {!isReopening && (
          <RadioGroup name="resolution" onChange={handleRadioGroupChange} disabled={isPending}>
            <RadioGroup.Label visuallyHidden>Dismissal reason</RadioGroup.Label>
            <FormControl>
              <Radio value={ResolutionType.Revoked} />
              <FormControl.Label>Revoked</FormControl.Label>
              <FormControl.Caption>{reasons.revokedDescription}</FormControl.Caption>
            </FormControl>
            <FormControl>
              <Radio value={ResolutionType.UsedInTests} />
              <FormControl.Label>Used in tests</FormControl.Label>
              <FormControl.Caption>{reasons.usedInTestsDescription}</FormControl.Caption>
            </FormControl>
            <FormControl>
              <Radio value={ResolutionType.FalsePositive} />
              <FormControl.Label>False positive</FormControl.Label>
              <FormControl.Caption>{reasons.falsePositiveDescription}</FormControl.Caption>
            </FormControl>
            <FormControl>
              <Radio value={ResolutionType.WontFix} />
              <FormControl.Label>Won&apos;t fix</FormControl.Label>
              <FormControl.Caption>{reasons.wontFixDescription}</FormControl.Caption>
            </FormControl>
          </RadioGroup>
        )}
        <div>
          <FormControl disabled={isPending}>
            <FormControl.Label>Comment</FormControl.Label>
            <Textarea
              placeholder="Add a comment"
              rows={5}
              maxLength={280}
              name="dismissal_comment"
              ref={dismissalComment}
              className="d-block width-full"
            />
          </FormControl>
        </div>
      </Stack>
    </Dialog>
  )
}
